from lesson_helpers import *
from bs4 import BeautifulSoup
import re
pops=[]
def add(k,title,body,ids):pops.append('<template data-pop="'+k+'" data-title="'+html.escape(title,quote=True)+'">'+body+ref(*ids)+'</template>')
summary=[('Le syndrome décrit une protéinurie glomérulaire durable, avec signes variables ; la cause et le stade se prouvent séparément.','EU-SYNDROMES'),('Le chiffre suisse global de MRC ne mesure pasN03 ; le dénominateur et la sélection changent toute fréquence.','CH-SGN-DEF'),('Perméabilité, inflammation et cicatrice ne sont pas synonymes ; leur combinaison guide bilan et traitement.','EU-HISTO'),('Vérifier la trajectoire, sécuriser une complication, caractériser les urines puis établir cause et risque.','CH-SGN-REF'),('Résultats datés, médicaments réellement pris, événements intercurrents et contexte familial sont des données diagnostiques.','INT-CKD-DRUG'),('La mesure de pression et l’examen du volume demandent méthode, comparaison et tolérance.','CH-SGN-PEC'),('Syndrome, cause, catégoriesG/A et morphologie décrivent des axes complémentaires.','INT-CKD-DEF'),('Confirmer le signe, la durée, la cause et le retentissement ; aucun test seul ne remplace ces niveaux.','INT-CKD-DEF'),('Un examen est utile lorsqu’il répond à une question et peut modifier une décision.','INT-GN-GENERAL'),('La discordance entre diagnostic ancien et évolution nouvelle rouvre les hypothèses.','INT-GN-MPGN'),('Associer protection rénale et traitement de cause ; respecter cible suisse, FI et sécurité de chaque produit.','CH-SGN-PEC'),('Le suivi associe fonction, protéines et clinique ; les seuils de variation déclenchent une évaluation sans prouver l’irréversibilité.','INT-CKD-RISK'),('Les tâches cliniques organisent l’entraînement ; les casMEDINA restent des exercices originaux.','CH-PROFILES'),('Ne pas confondre chronique et stable, pattern et cause, risque et indication immédiate de dialyse.','INT-CKD-KRT')]
for part in ['a','b']:
 path=CH/f'N03_{part}.html';txt=path.read_text()
 for i,(essential,sid) in enumerate(summary,1):
  m=re.search(r'(<section\b[^>]*id="n03-'+str(i)+r'"[^>]*>)(.*?)(</section>)',txt,re.S)
  if not m:continue
  soup=BeautifulSoup(m[2],'html.parser');title=soup.find(['h2','h3']).get_text(' ',strip=True);paras=re.findall(r'<p>(.*?)</p>',m[2],re.S)[:2]
  urls={a.get('href') for a in soup.select('a[data-reference-source]')};refs=[k for k,v in SOURCES.items() if v['url'] in urls]
  add('n03-exp-'+str(i),title,'<p>'+('</p><p>'.join(paras))+'</p>',refs)
  add('pareto-n03-'+str(i),'Raisonnement essentiel — '+title,'<p>'+essential+'</p><p>Revenir aux critères, à la méthode et aux limites de la section avant une décision individuelle.</p>',(sid,))
  txt=txt[:m.end(2)]+'<p>'+w('exp-'+str(i),'Comprendre le raisonnement')+'</p><button class="pareto-btn ui" data-k="pareto-n03-'+str(i)+'">▲ Loi de Pareto — Le raisonnement essentiel</button>'+txt[m.end(2):]
 path.write_text(txt)
add('n03-calcul-ratio','Rapport urinaire : le litre s’annule, pas l’analyte','''<p>Données fictives du même prélèvement : albumine60mg/L, créatinine1g/L. Le rapport albumine/créatinine est60÷1=60mg/g. Les litres s’annulent. Il s’agit d’albuminurieA2 selon les bornes du référentiel ; il ne s’agit pas d’une excrétion de60g/j.</p><p>Si les protéines totales sont à1,2g/L avec la même créatinine, le rapport protéines/créatinine est1,2g/g. Les deux résultats ne sont pas interchangeables : le premier quantifie l’albumine, le second toutes les protéines mesurées.</p><p>Le calcul ne prouve pas la chronicité. Vérifier conditions, répétition, contexte et évolution. Un seuil de traitement donné en protéines totales ne se lit pas avec un rapport d’albumine.</p>''',('INT-CKD-DEF','INT-GN-GENERAL'))
add('n03-calcul-variation','Variation relative : préciser le sens, la base et le délai','''<p>Débit fictif passant de68à51mL/min/1,73m² : baisse absolue68−51=17 ; baisse relative17÷68×100=25%. Elle dépasse le repère de20% qui appelle une évaluation selonKDIGO. Cela ne suffit pas à établir une progression irréversible.</p><p>Créatinine fictive passant de100à140µmol/L après modification d’un IEC : hausse relative(140−100)÷100×100=40%. Si elle survient dans les quatre semaines, elle dépasse le repère de30% discuté pour la sécurité de l’IEC/ARA. Il faut chercher état volémique, médicaments, potassium et autres causes selon la clinique.</p><p>Ces exemples sont indépendants. Une hausse de créatinine de30% n’est pas mathématiquement la même chose qu’une baisse de débit de30%. Ne pas interchanger les deux seuils ni ignorer une aggravation clinique qui reste sous une borne.</p>''',('INT-CKD-RISK','INT-CKD-TX'))
cases=[('Une fonction normale n’efface pas le dommage','''<p>Une personne a un débit estimé à95mL/min/1,73m² mais une albuminurie pathologique et un sédiment glomérulaire documentés depuis six mois. Une filtration conservée n’exclut pas une maladie rénale chronique : les marqueurs persistants apportent une autre voie diagnostique.</p><p>Il faut rechercher la cause et le risque. À l’inverse, un débit de75 isolé sans marqueur de dommage ne suffit pas à définir uneMRC. Le chiffre de filtration se lit avec l’ensemble du dossier.</p>''',('INT-CKD-DEF','CH-SGN-DEF')),('Ancien ne signifie pas inactif','''<p>Une personne suivie depuis plusieurs années développe une hausse rapide de créatinine, de nouveaux œdèmes et un purpura. Le caractère ancien de la maladie ne justifie pas d’attendre le bilan annuel. Évaluer gravité et causes réversibles, rechercher une maladie active et organiser rapidement le bilan spécialisé.</p><p>Une biopsie peut être discutée si elle doit changer le plan. L’alternative n’est pas entre corticoïde systématique et absence d’action ; la décision dépend de la cause, de l’activité et du retentissement.</p>''',('CH-HUG-ORIENT','INT-GN-GENERAL','EU-SYNDROMES')),('Un pattern n’est pas une cause','''<p>Le compte rendu décrit une lésion membranoproliférative. Le résultat oriente la recherche d’infection, de maladie auto-immune, d’immunoglobuline monoclonale ou de complément selon l’immunofluorescence. La lésion ne constitue pas à elle seule une étiologie.</p><p>La clinique, la biologie et le tissu se complètent. Une prescription immunosuppressive universelle risquerait de traiter des mécanismes différents de manière identique.</p>''',('INT-GN-MPGN','EU-HISTO')),('Une recommandation de classe ne modifie pas uneFI','''<p>Chez un adulte ayant un débit estimé à22mL/min/1,73m², une recommandation générale évoque un inhibiteurSGLT2 dès20. La FIForxiga consultée ne recommande pas son introduction sous25. On ne transforme donc pas le seuil de classe en autorisation de débuter ce produit à22.</p><p>Discuter les options avec le prescripteur en tenant compte du produit exact, de l’indication et des autres traitements. Une poursuite après introduction antérieure n’est pas la même décision qu’un début.</p>''',('CH-SGN-PEC','INT-CKD-TX','FI-FORXIGA'))]
for i,(title,body,refs) in enumerate(cases,1):add('n03-cas-'+str(i),'Cas '+str(i)+' — '+title,'<p><b>Exercice fictif original.</b></p>'+body,refs)
# Entry points for the two calculations in the examination and normal-science contexts.
for part,anchor,k,label in [('c','e-fonction','calcul-variation','Calculer une variation relative'),('c','s-bio-content','calcul-ratio','Calculer un rapport urinaire')]:
 path=CH/f'N03_{part}.html';txt=path.read_text();txt=re.sub(r'(<section\b[^>]*id="n03-'+anchor+r'"[^>]*>.*?)(</section>)',lambda m:m[1]+'<p>'+w(k,label)+'</p>'+m[2],txt,count=1,flags=re.S);path.write_text(txt)
quiz=[('Un débitG1 exclut-il touteMRC ?','Non, des marqueurs de dommage persistants peuvent établir la maladie.','Oui, seule la filtration compte.','Durée et marqueurs urinaires, structuraux ou histologiques sont complémentaires au débit.','INT-CKD-DEF'),('Une baisse68→51 correspond à quelle variation ?','Une baisse de25%.','Une baisse de17%.','(68−51)÷68×100=25%. Le repère appelle une évaluation, pas une conclusion automatique d’irréversibilité.','INT-CKD-RISK'),('Une lésionMPGN donne-t-elle à elle seule l’étiologie ?','Non, il faut rechercher son mécanisme et sa cause.','Oui, tous les cas ont le même traitement.','Le pattern peut résulter de mécanismes différents ; l’immunofluorescence et le contexte orientent.','INT-GN-MPGN'),('Un débitG5 impose-t-il immédiatement une dialyse ?','Non, la décision associe clinique, biologie et préférences.','Oui, le chiffre suffit.','Préparer la suppléance et décider de la débuter sont deux décisions distinctes.','INT-CKD-KRT')]
p=CH/'N03_b.html';txt=p.read_text();q=''.join('<div class="quiz ui"><p>'+question+'</p><button data-ok="1">'+yes+'</button><button data-ok="0">'+no+'</button><p class="fb" hidden>'+ex+'</p></div>'+ref(sid) for question,yes,no,ex,sid in quiz);txt=re.sub(r'(<section\b[^>]*id="n03-13"[^>]*>.*?)(</section>)',lambda m:m[1]+q+m[2],txt,count=1,flags=re.S);p.write_text(txt)
save('pop1','\n'.join(pops[:16]));save('pop2','\n'.join(pops[16:]));print(len(pops),'fenêtres,14Pareto,4quiz')
